const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;
const tokenizer = @import("tokenizer.zig");
const optimizer = @import("optimizer.zig");
const runtime = @import("runtime.zig");

pub const QSM = struct {
    allocator: Allocator,
    contexts: ArrayList([]f64),
    interference: f64,

    pub fn init(allocator: Allocator) QSM {
        return .{
            .allocator = allocator,
            .contexts = ArrayList([]f64).init(allocator),
            .interference = 0.0,
        };
    }

    pub fn deinit(self: *QSM) void {
        for (self.contexts.items) |ctx| {
            self.allocator.free(ctx);
        }
        self.contexts.deinit();
    }

    pub fn multiplex(self: *QSM, synapse: f64, contexts: []const []const f64) !void {
        self.interference = 0.0;
        for (contexts) |ctx| {
            var phase: f64 = 0.0;
            var amp: f64 = 0.0;
            for (ctx) |c| {
                phase += math.pi * c;
                amp += c / 10.0;
            }
            self.interference += math.sin(phase) * amp;
        }
        self.interference *= synapse;
    }

    pub fn getInterference(self: *const QSM) f64 {
        return self.interference;
    }
};

pub const MES = struct {
    allocator: Allocator,
    codec: fn ([]const u8) []u8,
    condition: bool,

    pub fn init(allocator: Allocator) MES {
        return .{
            .allocator = allocator,
            .codec = defaultCodec,
            .condition = false,
        };
    }

    pub fn deinit(self: *MES) void {
        _ = self;
    }

    pub fn selfOverwrite(self: *MES, cond: bool) void {
        self.condition = cond;
    }

    pub fn process(self: *MES, input: []const u8) ![]u8 {
        if (self.condition) {
            return reverseString(self.allocator, input);
        } else {
            return self.codec(input);
        }
    }

    fn defaultCodec(_: []const u8) []u8 {
        const alloc = std.heap.page_allocator;
        var result = alloc.alloc(u8, 1) catch return &.{};
        result[0] = 0;
        return result;
    }

    fn reverseString(allocator: Allocator, s: []const u8) ![]u8 {
        const len = s.len;
        const result = try allocator.alloc(u8, len);
        for (0..len) |i| {
            result[i] = s[len - 1 - i];
        }
        return result;
    }
};

pub const EHM = struct {
    allocator: Allocator,
    state: f64,
    reflection: []u8,

    pub fn init(allocator: Allocator) EHM {
        return .{
            .allocator = allocator,
            .state = 1.0,
            .reflection = &.{},
        };
    }

    pub fn deinit(self: *EHM) void {
        self.allocator.free(self.reflection);
    }

    pub fn update(self: *EHM, refl: []const u8) void {
        self.allocator.free(self.reflection);
        self.reflection = self.allocator.dupe(u8, refl) catch &.{};
        self.state = self.state * 1.1;
    }

    pub fn getState(self: *const EHM) f64 {
        return self.state;
    }
};

pub const MXSI = struct {
    voltage: f64,
