pub const CPS = struct {
    allocator: Allocator,
    thoughts: ArrayList([]u8),
    topology: ArrayList(struct { thought: []u8, phase: f64 }),

    pub fn init(allocator: Allocator) CPS {
        return .{
            .allocator = allocator,
            .thoughts = ArrayList([]u8).init(allocator),
            .topology = ArrayList(struct { thought: []u8, phase: f64 }).init(allocator),
        };
    }

    pub fn deinit(self: *CPS) void {
        for (self.thoughts.items) |t| {
            self.allocator.free(t);
        }
        self.thoughts.deinit();
        for (self.topology.items) |top| {
            self.allocator.free(top.thought);
        }
        self.topology.deinit();
    }

    pub fn addThought(self: *CPS, thought: []const u8) !void {
        const dup = try self.allocator.dupe(u8, thought);
        try self.thoughts.append(dup);
    }

    pub fn computeTopology(self: *CPS) !void {
        self.topology.clearAndFree();
        for (self.thoughts.items) |th| {
            const len = th.len;
            const phase = math.sqrt(@as(f64, @floatFromInt(len)));
            const top = .{ .thought = th, .phase = phase };
            try self.topology.append(top);
        }
    }

    pub fn getTopology(self: *const CPS) []const struct { thought: []u8, phase: f64 } {
        return self.topology.items;
    }
};

pub const TensorCore = struct {
    allocator: Allocator,
    shape: []usize,
    data: []f64,
    qsm: QSM,
    mes: MES,
    ehm: EHM,
    mxsi: MXSI,
    cps: CPS,
    tokenizer: tokenizer.Tokenizer,
    optimizer: optimizer.ZOOptimizer,
    runtime: runtime.Runtime,

    pub fn init(allocator: Allocator, shape: []const usize) !TensorCore {
        var total: usize = 1;
        for (shape) |d| total *= d;
        const data = try allocator.alloc(f64, total);
        @memset(data, 0.0);
        var tc = TensorCore{
            .allocator = allocator,
            .shape = try allocator.dupe(usize, shape),
            .data = data,
            .qsm = QSM.init(allocator),
            .mes = MES.init(allocator),
            .ehm = EHM.init(allocator),
            .mxsi = MXSI.init(),
            .cps = CPS.init(allocator),
            .tokenizer = try tokenizer.Tokenizer.init(allocator),
            .optimizer = optimizer.ZOOptimizer.init(allocator),
            .runtime = runtime.Runtime.init(allocator),
        };
        return tc;
    }

    pub fn deinit(self: *TensorCore) void {
        self.qsm.deinit();
        self.mes.deinit();
        self.ehm.deinit();
        self.cps.deinit();
        self.tokenizer.deinit();
        self.optimizer.deinit();
        self.runtime.deinit();
        self.allocator.free(self.shape);
        self.allocator.free(self.data);
    }

    pub fn reshape(self: *TensorCore, new_shape: []const usize) !void {
        var old_total: usize = 1;
        for (self.shape) |d| old_total *= d;
        var new_total: usize = 1;
        for (new_shape) |d| new_total *= d;
        if (old_total != new_total) return error.InvalidShape;
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
    }

    fn shapeMatches(self: *const TensorCore, other: *const TensorCore) bool {
        if (self.shape.len != other.shape.len) return false;
        for (self.shape, other.shape) |a, b| if (a != b) return false;
        return true;
    }

    pub fn add(self: *TensorCore, other: *const TensorCore) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, 0..) |*v, i| v.* += other.data[i];
    }

    pub fn mul(self: *TensorCore, other: *const TensorCore) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, 0..) |*v, i| v.* *= other.data[i];
    }

    pub fn matmul(self: *TensorCore, other: *const TensorCore) !TensorCore {
        if (self.shape.len != 2 or other.shape.len != 2) return error.NotMatrix;
        if (self.shape[1] != other.shape[0]) return error.InvalidDimensions;
        const rows = self.shape[0];
        const cols = other.shape[1];
        const inner = self.shape[1];
        var out = try TensorCore.init(self.allocator, &[_]usize{ rows, cols });
        for (0..rows) |i| {
            for (0..cols) |j| {
                var sum: f64 = 0.0;
                for (0..inner) |k| {
                    sum += self.data[i * inner + k] * other.data[k * cols + j];
                }
                out.data[i * cols + j] = sum;
            }
        }
        return out;
    }

    pub fn softmax(self: *TensorCore, axis: usize) !void {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        var maxv: f64 = -math.inf(f64);
        if (axis == 0) {
            for (0..rows) |i| {
                var row_max: f64 = -math.inf(f64);
                for (0..cols) |j| row_max = math.max(row_max, self.data[i * cols + j]);
                maxv = math.max(maxv, row_max);
            }
        } else {
            for (0..cols) |j| {
                var col_max: f64 = -math.inf(f64);
                for (0..rows) |i| col_max = math.max(col_max, self.data[i * cols + j]);
                maxv = math.max(maxv, col_max);
            }
        }
        var sumexp: f64 = 0.0;
        for (0..rows) |i| {
            for (0..cols) |j| {
                const idx = i * cols + j;
                const shifted = self.data[idx] - maxv;
                self.data[idx] = math.exp(shifted);
                sumexp += self.data[idx];
            }
        }
        const inv = 1.0 / sumexp;
        for (0..rows) |i| {
            for (0..cols) |j| {
                const idx = i * cols + j;
                self.data[idx] *= inv;
            }
        }
    }

    pub fn argmax(self: *TensorCore, axis: usize) ![]usize {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        if (axis == 0) {
            var out = try self.allocator.alloc(usize, cols);
            for (0..cols) |j| {
                var best: usize = 0;
                var maxv = self.data[0 * cols + j];
                for (1..rows) |i| {
                    const v = self.data[i * cols + j];
                    if (v > maxv) { maxv = v; best = i; }
                }
                out[j] = best;
            }
            return out;
        } else {
            var out = try self.allocator.alloc(usize, rows);
            for (0..rows) |i| {
                var best: usize = 0;
                var maxv = self.data[i * cols + 0];
                for (1..cols) |j| {
                    const v = self.data[i * cols + j];
                    if (v > maxv) { maxv = v; best = j; }
                }
                out[i] = best;
            }
            return out;
        }
    }

    pub fn integrateQSM(self: *TensorCore, synapse: f64, contexts: []const []const f64) !void {
        try self.qsm.multiplex(synapse, contexts);
        const interf = self.qsm.getInterference();
        for (self.data) |*v| v.* += interf;
    }

    pub fn applyMES(self: *TensorCore, cond: bool, input_str: []const u8) ![]u8 {
        self.mes.selfOverwrite(cond);
        return self.mes.process(input_str);
    }

    pub fn reflectEHM(self: *TensorCore, refl: []const u8) void {
        self.ehm.update(refl);
        const s = self.ehm.getState();
        for (self.data) |*v| v.* *= s;
    }

    pub fn adjustMXSI(self: *TensorCore, v: f64, t: f64) void {
        self.mxsi.compute(v, t);
        const c = self.mxsi.getConductance();
        for (self.data) |*x| x.* *= c;
    }

    pub fn phaseCPS(self: *TensorCore, thoughts: []const []const u8) !void {
        for (thoughts) |th| try self.cps.addThought(th);
        try self.cps.computeTopology();
    }

    pub fn run(self: *TensorCore, input: []const f64) ![]f64 {
        return self.runtime.execute(input, self.data);
    }
};
pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const A = gpa.allocator();

    var a = try TensorCore.init(A, &[_]usize{2,3});
    defer a.deinit();
    a.data[0] = 1.0; a.data[1] = 2.0; a.data[2] = 3.0;
    a.data[3] = 4.0; a.data[4] = 5.0; a.data[5] = 6.0;

    var b = try TensorCore.init(A, &[_]usize{3,2});
    defer b.deinit();
    b.data[0] = 1.0; b.data[1] = 2.0;
    b.data[2] = 3.0; b.data[3] = 4.0;
    b.data[4] = 5.0; b.data[5] = 6.0;

    var c = try a.matmul(&b);
    defer c.deinit();

    try a.softmax(1);
    try a.integrateQSM(1.0, &[_][]const f64{ &[_]f64{1.0, 2.0}, &[_]f64{3.0} });
    _ = try a.applyMES(true, "test");
    a.reflectEHM("reflect");
    a.adjustMXSI(1.0, 300.0);
    try a.phaseCPS(&[_][]const u8{ "thought1", "thought2" });
    const out = try a.run(&[_]f64{1.0, 2.0});
    defer A.free(out);
}
