    pub fn tokenize(self: *const Tokenizer, text: []const u8) ![]u32 {
        var out = std.ArrayList(u32).init(self.allocator);
        defer out.deinit();
        try out.append(self.bos_token);
        for (text) |ch| {
            var found: bool = false;
            var it = self.vocab.iterator();
            while (it.next()) |e| {
                const id = e.key_ptr.*;
                const s = e.value_ptr.*;
                if (s.len == 1 and s[0] == ch) {
                    try out.append(id);
                    found = true;
                    break;
                }
