const std = @import("std");
const math = std.math;

pub const ZOOptimizer = struct {
    allocator: std.mem.Allocator,
    learning_rate: f64,
    perturbation: f64,

    pub fn init(allocator: std.mem.Allocator) ZOOptimizer {
        return .{
            .allocator = allocator,
            .learning_rate = 0.01,
            .perturbation = 0.001,
        };
    }

    pub fn deinit(self: *ZOOptimizer) void {
        _ = self;
    }

    pub fn step(self: *ZOOptimizer, params: []f64, lr: f64) !void {
        self.learning_rate = lr;
        const n = params.len;
        if (n == 0) return;
        var f_plus: f64 = 0.0;
        var f_minus: f64 = 0.0;
        for (0..n) |i| {
            const xp = params[i] + self.perturbation;
            const xm = params[i] - self.perturbation;
            f_plus += xp * xp;
            f_minus += xm * xm;
        }
        const grad_est = (f_plus - f_minus) / (2.0 * self.perturbation);
        const per_param = grad_est / @as(f64, @floatFromInt(n));
        for (0..n) |i| {
            params[i] -= self.learning_rate * per_param;
        }
    }
};
