const std = @import("std");

pub const Runtime = struct {
    allocator: std.mem.Allocator,
    stack: std.ArrayList(f64),
    registers: [32]f64,

    pub fn init(allocator: std.mem.Allocator) Runtime {
        return .{
            .allocator = allocator,
            .stack = std.ArrayList(f64).init(allocator),
            .registers = [_]f64{0} ** 32,
        };
    }

    pub fn deinit(self: *Runtime) void {
        self.stack.deinit();
    }

    pub fn execute(self: *Runtime, input: []const f64, weights: []const f64) ![]f64 {
        self.stack.clearAndFree();
        const n = @min(input.len, weights.len);
        var acc: f64 = 0.0;
        for (0..n) |i| {
            acc += input[i] * weights[i];
        }
        try self.stack.append(acc);
        return try self.stack.toOwnedSlice();
    }
};
