const std = @import("std");

pub const DType = enum {
    f16,
    f32,
    f64,
    i32,
    i64,
    u32,
    u64,
};

pub const Shape = struct {
    dims: []usize,

    pub fn init(allocator: std.mem.Allocator, dims: []const usize) !Shape {
        return Shape{ .dims = try allocator.dupe(usize, dims) };
    }

