// hardware.zig
const std = @import("std");

pub const DeviceType = enum { cpu, cuda, metal, rocm, vulkan };

pub const Device = struct {
    kind: DeviceType,
    id: u32,

    pub fn cpu() Device {
        return .{ .kind = .cpu, .id = 0 };
    }

    pub fn with(kind: DeviceType, id: u32) Device {
        return .{ .kind = kind, .id = id };
    }
};

pub const BLAS = struct {
    allocator: std.mem.Allocator,
    device: Device,

    pub fn init(allocator: std.mem.Allocator, device: Device) BLAS {
        return .{ .allocator = allocator, .device = device };
    }

    pub fn deinit(self: *BLAS) void {
        _ = self;
    }

    pub fn gemm(self: *BLAS, m: usize, n: usize, k: usize, a: []const f64, b: []const f64, c: []f64) void {
        _ = self;
        for (0..m) |i| {
            for (0..n) |j| {
                var acc: f64 = 0.0;
                for (0..k) |p| {
                    acc += a[i * k + p] * b[p * n + j];
                }
                c[i * n + j] = acc;
            }
        }
    }

    pub fn axpy(self: *BLAS, n: usize, alpha: f64, x: []const f64, y: []f64) void {
        _ = self;
        for (0..n) |i| y[i] = alpha * x[i] + y[i];
    }

    pub fn softmax(self: *BLAS, rows: usize, cols: usize, x: []f64) void {
        _ = self;
        for (0..rows) |i| {
            var maxv: f64 = -std.math.inf(f64);
            for (0..cols) |j| maxv = std.math.max(maxv, x[i * cols + j]);
            var sum: f64 = 0.0;
            for (0..cols) |j| {
                const idx = i * cols + j;
                x[idx] = std.math.exp(x[idx] - maxv);
                sum += x[idx];
            }
            const inv = 1.0 / sum;
            for (0..cols) |j| x[i * cols + j] *= inv;
        }
    }
};
