const std = @import("std");
const math = std.math;

pub const ZOOptimizer = struct {
    allocator: std.mem.Allocator,
    learning_rate: f64,
    perturbation: f64,

    pub fn init(allocator: std.mem.Allocator) ZOOptimizer {
        return .{
            .allocator = allocator,
            .learning_rate = 1e-2,
            .perturbation = 1e-3,
        };
    }

    pub fn deinit(self: *ZOOptimizer) void {
        _ = self;
    }

    pub fn step(self: *ZOOptimizer, params: []f64, lr: f64) !void {
        self.learning_rate = lr;
        if (params.len == 0) return;

        var fp: f64 = 0.0;
        var fm: f64 = 0.0;

        for (params) |v| {
            const xp = v + self.perturbation;
            const xm = v - self.perturbation;
            fp += xp * xp;
            fm += xm * xm;
        }

        const grad_est = (fp - fm) / (2.0 * self.perturbation);
        const per = grad_est / @as(f64, @floatFromInt(params.len));
        for (params, 0..) |_, i| {
            params[i] -= self.learning_rate * per;
        }
    }
};
