const std = @import("std");
const hardware = @import("hardware.zig");

pub const Linear = struct {
    allocator: std.mem.Allocator,
    in_features: usize,
    out_features: usize,
    weight: []f64,
    bias: []f64,

    pub fn init(allocator: std.mem.Allocator, in_features: usize, out_features: usize) !Linear {
        var rng = std.rand.DefaultPrng.init(0xC0FFEEBEEF);
        const r = rng.random();

        const w = try allocator.alloc(f64, in_features * out_features);
        const b = try allocator.alloc(f64, out_features);
        for (0..out_features) |j| {
            for (0..in_features) |i| {
                w[j * in_features + i] = (r.float(f64) - 0.5) * 0.02;
            }
            b[j] = 0.0;
        }
        return .{
            .allocator = allocator,
            .in_features = in_features,
            .out_features = out_features,
            .weight = w,
            .bias = b,
        };
    }

    pub fn deinit(self: *Linear) void {
        self.allocator.free(self.weight);
        self.allocator.free(self.bias);
    }

    pub fn forward(self: *const Linear, x: []const f64, out: []f64) void {
        // x: [in], out: [out]
        const blas = hardware.BLAS.init(self.allocator, hardware.Device.cpu());
        blas.gemm(1, self.out_features, self.in_features, x, self.weight, out);
        for (0..self.out_features) |j| out[j] += self.bias[j];
    }
};

pub const Softmax = struct {
    pub fn forward(_: *const Softmax, x: []f64) void {
        const rows: usize = 1;
        const cols: usize = x.len;
        const blas = hardware.BLAS.init(std.heap.page_allocator, hardware.Device.cpu());
        blas.softmax(rows, cols, x);
    }
};
