// model.zig
const std = @import("std");
const layers = @import("layers.zig");
const tokenizer = @import("tokenizer.zig");
const runtime = @import("runtime.zig");

pub const LLM = struct {
    allocator: std.mem.Allocator,
    tok: tokenizer.Tokenizer,
    emb: layers.Linear,
    head: layers.Linear,
    softmax: layers.Softmax,
    rt: runtime.Runtime,

    pub fn init(allocator: std.mem.Allocator, vocab_size: usize, hidden: usize) !LLM {
        return .{
            .allocator = allocator,
            .tok = try tokenizer.Tokenizer.init(allocator),
            .emb = try layers.Linear.init(allocator, vocab_size, hidden),
            .head = try layers.Linear.init(allocator, hidden, vocab_size),
            .softmax = .{},
            .rt = runtime.Runtime.init(allocator),
        };
    }

    pub fn deinit(self: *LLM) void {
        self.tok.deinit();
        self.emb.deinit();
        self.head.deinit();
        self.rt.deinit();
    }

    pub fn logits(self: *LLM, text: []const u8) ![]f64 {
        const ids = try self.tok.tokenize(text);
        defer self.allocator.free(ids);

        const vocab = self.head.out_features;
        const hidden = self.emb.out_features;

        var h = try self.allocator.alloc(f64, hidden);
        defer self.allocator.free(h);
        @memset(h, 0);

        // Simple bag-of-chars embedding: sum of token one-hots projected
        var tmp_in = try self.allocator.alloc(f64, self.emb.in_features);
        defer self.allocator.free(tmp_in);
        @memset(tmp_in, 0);

        for (ids) |tid| {
            if (tid < tmp_in.len) tmp_in[tid] += 1.0;
        }

        self.emb.forward(tmp_in, h);

        var out = try self.allocator.alloc(f64, vocab);
        self.head.forward(h, out);
        return out;
    }

    pub fn predict(self: *LLM, text: []const u8) ![]u8 {
        var l = try self.logits(text);
        defer self.allocator.free(l);
        self.softmax.forward(l);

        // Argmax
        var best: usize = 0;
        var maxv: f64 = l[0];
        for (1..l.len) |i| {
            if (l[i] > maxv) {
                maxv = l[i];
                best = i;
            }
        }

        var toks = try std.ArrayList(u32).initCapacity(self.allocator, 3);
        defer toks.deinit();
        try toks.append(best);
        const bytes = try self.tok.detokenize(toks.items);
        return bytes;
    }
};
