// attention.zig
const std = @import("std");

pub const Attention = struct {
    allocator: std.mem.Allocator,
    d_model: usize,
    n_heads: usize,
    w_q: []f64,
    w_k: []f64,
    w_v: []f64,
    w_o: []f64,

    pub fn init(allocator: std.mem.Allocator, d_model: usize, n_heads: usize) !Attention {
        if (d_model % n_heads != 0) return error.InvalidHeadSize;
        const d_head = d_model / n_heads;

        const w_q = try allocator.alloc(f64, d_model * d_model);
        const w_k = try allocator.alloc(f64, d_model * d_model);
        const w_v = try allocator.alloc(f64, d_model * d_model);
        const w_o = try allocator.alloc(f64, d_model * d_model);

        var prng = std.rand.DefaultPrng.init(0xA11CEBEEF);
        const r = prng.random();
        const scale: f64 = 0.02;

        for (w_q) |*x| x.* = (r.float(f64) - 0.5) * scale;
        for (w_k) |*x| x.* = (r.float(f64) - 0.5) * scale;
        for (w_v) |*x| x.* = (r.float(f64) - 0.5) * scale;
        for (w_o) |*x| x.* = (r.float(f64) - 0.5) * scale;

        return .{
            .allocator = allocator,
            .d_model = d_model,
            .n_heads = n_heads,
            .w_q = w_q,
            .w_k = w_k,
            .w_v = w_v,
            .w_o = w_o,
        };
    }

    pub fn deinit(self: *Attention) void {
        self.allocator.free(self.w_q);
        self.allocator.free(self.w_k);
        self.allocator.free(self.w_v);
        self.allocator.free(self.w_o);
    }

    fn matvec(w: []const f64, rows: usize, cols: usize, x: []const f64, y: []f64) void {
        for (0..rows) |i| {
            var acc: f64 = 0.0;
            for (0..cols) |j| {
                acc += w[i * cols + j] * x[j];
            }
            y[i] = acc;
        }
    }

    fn softmax_inplace(x: []f64) void {
        var maxv: f64 = -std.math.inf(f64);
        for (x) |v| if (v > maxv) maxv = v;
        var sum: f64 = 0.0;
        for (x, 0..) |v, i| {
            const e = std.math.exp(v - maxv);
            x[i] = e;
            sum += e;
        }
        const inv = 1.0 / sum;
        for (x, 0..) |_, i| x[i] *= inv;
    }

    pub fn forward(self: *const Attention, x_seq: []const f64, seq_len: usize, out: []f64) !void {
        const d_model = self.d_model;
        if (x_seq.len != seq_len * d_model) return error.Shape;
        if (out.len != seq_len * d_model) return error.Shape;

        var q = try self.allocator.alloc(f64, seq_len * d_model);
        defer self.allocator.free(q);
        var k = try self.allocator.alloc(f64, seq_len * d_model);
        defer self.allocator.free(k);
        var v = try self.allocator.alloc(f64, seq_len * d_model);
        defer self.allocator.free(v);
        var o = try self.allocator.alloc(f64, seq_len * d_model);
        defer self.allocator.free(o);
        @memset(q, 0);
        @memset(k, 0);
        @memset(v, 0);
        @memset(o, 0);

        // Compute Q, K, V per token
        for (0..seq_len) |t| {
            const x_t = x_seq[t * d_model .. (t + 1) * d_model];
            const q_t = q[t * d_model .. (t + 1) * d_model];
            const k_t = k[t * d_model .. (t + 1) * d_model];
            const v_t = v[t * d_model .. (t + 1) * d_model];
            matvec(self.w_q, d_model, d_model, x_t, q_t);
            matvec(self.w_k, d_model, d_model, x_t, k_t);
            matvec(self.w_v, d_model, d_model, x_t, v_t);
        }

        const n_heads = self.n_heads;
        const d_head = d_model / n_heads;
        var attn = try self.allocator.alloc(f64, seq_len * seq_len);
        defer self.allocator.free(attn);
        var z = try self.allocator.alloc(f64, seq_len * d_model);
        defer self.allocator.free(z);
        @memset(z, 0);

        const scale = 1.0 / std.math.sqrt(@as(f64, @floatFromInt(d_head)));

        // For each head, compute scaled dot-product attention with causal mask
        for (0..n_heads) |h| {
            const h_off = h * d_head;
            // Scores
            for (0..seq_len) |tq| {
                for (0..seq_len) |tk| {
                    var s: f64 = 0.0;
                    const qv = q[tq * d_model + h_off .. tq * d_model + h_off + d_head];
                    const kv = k[tk * d_model + h_off .. tk * d_model + h_off + d_head];
                    for (0..d_head) |i| s += qv[i] * kv[i];
                    var masked = s * scale;
                    if (tk > tq) masked = -1e9;
                    attn[tq * seq_len + tk] = masked;
                }
                const row = attn[tq * seq_len .. (tq + 1) * seq_len];
                softmax_inplace(row);
            }

            // Weighted sum of V
            for (0..seq_len) |t| {
                const out_h = z[t * d_model + h_off .. t * d_model + h_off + d_head];
                var tmp: f64 = 0.0;
                for (0..d_head) |i| out_h[i] = 0.0;
                for (0..seq_len) |tk| {
                    const a = attn[t * seq_len + tk];
                    const vv = v[tk * d_model + h_off .. tk * d_model + h_off + d_head];
                    for (0..d_head) |i| out_h[i] += a * vv[i];
                }
            }
        }

        // Final projection
        for (0..seq_len) |t| {
            const z_t = z[t * d_model .. (t + 1) * d_model];
            const o_t = o[t * d_model .. (t + 1) * d_model];
            matvec(self.w_o, d_model, d_model, z_t, o_t);
        }

        @memcpy(out, o);
    }
};
