const std = @import("std");

pub const LayerNorm = struct {
    allocator: std.mem.Allocator,
    d_model: usize,
    gamma: []f64,
    beta: []f64,
    eps: f64,

    pub fn init(allocator: std.mem.Allocator, d_model: usize, eps: f64) !LayerNorm {
        const gamma = try allocator.alloc(f64, d_model);
        const beta = try allocator.alloc(f64, d_model);
        for (0..d_model) |i| {
            gamma[i] = 1.0;
            beta[i] = 0.0;
        }
        return .{
            .allocator = allocator,
            .d_model = d_model,
            .gamma = gamma,
            .beta = beta,
            .eps = eps,
        };
    }

    pub fn deinit(self: *LayerNorm) void {
        self.allocator.free(self.gamma);
        self.allocator.free(self.beta);
    }

    pub fn forward(self: *const LayerNorm, x: []f64, seq_len: usize) !void {
        const d = self.d_model;
        if (x.len != seq_len * d) return error.Shape;

        for (0..seq_len) |t| {
            const row = x[t * d .. (t + 1) * d];
            var mean: f64 = 0.0;
            for (row) |v| mean += v;
            mean /= @as(f64, @floatFromInt(d));

            var varsum: f64 = 0.0;
            for (row) |v| {
                const dlt = v - mean;
                varsum += dlt * dlt;
            }
            const var = varsum / @as(f64, @floatFromInt(d));
            const inv = 1.0 / std.math.sqrt(var + self.eps);

            for (0..d) |i| {
                const nrm = (row[i] - mean) * inv;
                row[i] = nrm * self.gamma[i] + self.beta[i];
            }
        }
    }
};
