pub fn gelu_inplace(x: []f64) void {
    // Approximate GELU
    // 0.5 * x * (1 + tanh( sqrt(2/pi) * (x + 0.044715 * x^3) ))
    const k: f64 = 0.7978845608028654;
    for (x, 0..) |v, i| {
        const x3 = v * v * v;
        const inner = k * (v + 0.044715 * x3);
        const t = std.math.tanh(inner);
        x[i] = 0.5 * v * (1.0 + t);
