        const d = self.d_model;
        const h = self.d_hidden;
        if (x_seq.len != seq_len * d) return error.Shape;

        var tmp = try self.allocator.alloc(f64, seq_len * h);
        defer self.allocator.free(tmp);

        for (0..seq_len) |t| {
            const x_t = x_seq[t * d .. (t + 1) * d];
            const h_t = tmp[t * h .. (t + 1) * h];
            matvec(self.w1, h, d, x_t, h_t);
            for (0..h) |i| h_t[i] += self.b1[i];
            gelu.gelu_inplace(h_t);
        }

        for (0..seq_len) |t| {
            const h_t = tmp[t * h .. (t + 1) * h];
            const o_t = x_seq[t * d .. (t + 1) * d];
            matvec(self.w2, d, h, h_t, o_t);
            for (0..d) |i| o_t[i] += self.b2[i];
        }
    }
};
