// posenc.zig
const std = @import("std");

pub fn add_sinusoidal_posenc(x: []f64, seq_len: usize, d_model: usize) !void {
    if (x.len != seq_len * d_model) return error.Shape;
    for (0..seq_len) |t| {
        const pos = @as(f64, @floatFromInt(t));
        for (0..d_model) |i| {
            const k = @as(f64, @floatFromInt(i));
            const div = std.math.pow(f64, 10000.0, -2.0 * std.math.floor(k / 2.0) / @as(f64, @floatFromInt(d_model)));
            if ((i & 1) == 0) {
                x[t * d_model + i] += std.math.sin(pos * div);
            } else {
                x[t * d_model + i] += std.math.cos(pos * div);
            }
        }
    }
}
