// trainer.zig
const std = @import("std");
const model = @import("model.zig");

pub const Trainer = struct {
    allocator: std.mem.Allocator,
    opt_lr: f64,

    pub fn init(allocator: std.mem.Allocator, lr: f64) Trainer {
        return .{ .allocator = allocator, .opt_lr = lr };
    }

    pub fn step_logits(self: *Trainer, llm: *model.LLM, text: []const u8) !f64 {
        // Forward to logits
        const logits = try llm.logits(text);
        defer self.allocator.free(logits);

        // Cross-entropy to next char of same input (toy)
        if (text.len == 0) return 0.0;

        const target = text[text.len - 1];
        var best: usize = 0;
        var maxv: f64 = logits[0];
        for (1..logits.len) |i| {
            if (logits[i] > maxv) {
                maxv = logits[i];
                best = i;
            }
        }

        const loss = -std.math.log(maxv + 1e-9);
        _ = target;
        return loss;
    }
};
