// utils.zig
const std = @import("std");

pub fn argmax(x: []const f64) usize {
    var best: usize = 0;
    var maxv: f64 = x[0];
    for (1..x.len) |i| {
        if (x[i] > maxv) {
            maxv = x[i];
            best = i;
        }
    }
    return best;
}

pub fn softmax_inplace(x: []f64) void {
    var maxv: f64 = -std.math.inf(f64);
    for (x) |v| if (v > maxv) maxv = v;
    var sum: f64 = 0.0;
    for (x, 0..) |v, i| {
        const e = std.math.exp(v - maxv);
        x[i] = e;
        sum += e;
    }
    const inv = 1.0 / sum;
    for (x, 0..) |_, i| x[i] *= inv;
}
