        const n = try br.readIntLittle(u64);
        var buf = try allocator.alloc(f64, @as(usize, @intCast(n)));
        const bytes = std.mem.sliceAsBytes(buf);
        try br.readNoEof(bytes);
        _ = self;
        return buf;
    }
