// rope.zig
const std = @import("std");

pub fn apply_rope_inplace(x: []f64, seq_len: usize, d_model: usize) !void {
    if (d_model % 2 != 0) return error.EvenOnly;
    if (x.len != seq_len * d_model) return error.Shape;

    const half = d_model / 2;
    for (0..seq_len) |t| {
        const angle = 0.0001 * @as(f64, @floatFromInt(t));
        for (0..half) |i| {
            const a = x[t * d_model + i];
            const b = x[t * d_model + half + i];
            const ca = std.math.cos(angle);
            const sa = std.math.sin(angle);
            x[t * d_model + i] = a * ca - b * sa;
            x[t * d_model + half + i] = a * sa + b * ca;
        }
    }
}
