    pub fn deinit(self: *EncoderBlock) void {
        self.self_attn.deinit();
        self.ln1.deinit();
        self.ln2.deinit();
        self.mlp.deinit();
    }

    pub fn forward(self: *EncoderBlock, x: []f64, seq_len: usize) !void {
        const d = self.d_model;
        var res = try self.allocator.alloc(f64, x.len);
        defer self.allocator.free(res);
        @memcpy(res, x);

        try self.ln1.forward(x, seq_len);
        var att_out = try self.allocator.alloc(f64, x.len);
        defer self.allocator.free(att_out);
        try self.self_attn.forward(x, seq_len, att_out);
        for (0..seq_len) |t| {
            for (0..d) |i| {
                x[t * d + i] = res[t * d + i] + att_out[t * d + i];
            }
        }

        @memcpy(res, x);
        try self.ln2.forward(x, seq_len);
        try self.mlp.forward(x, seq_len);
        for (0..seq_len) |t| {
            for (0..d) |i| {
                x[t * d + i] = res[t * d + i] + x[t * d + i];
            }
        }
    }
