// embeddings.zig
const std = @import("std");

pub const Embeddings = struct {
    allocator: std.mem.Allocator,
    vocab_size: usize,
    d_model: usize,
    table: []f64,

    pub fn init(allocator: std.mem.Allocator, vocab_size: usize, d_model: usize) !Embeddings {
        const table = try allocator.alloc(f64, vocab_size * d_model);
        var prng = std.rand.DefaultPrng.init(0xBADC0FFEE);
        const r = prng.random();
        const scale: f64 = 0.02;
        for (table) |*x| x.* = (r.float(f64) - 0.5) * scale;
        return .{
            .allocator = allocator,
            .vocab_size = vocab_size,
            .d_model = d_model,
            .table = table,
        };
    }

    pub fn deinit(self: *Embeddings) void {
        self.allocator.free(self.table);
    }

    pub fn forward(self: *const Embeddings, ids: []const u32, out: []f64) !void {
        if (out.len != ids.len * self.d_model) return error.Shape;
        for (ids, 0..) |tid, t| {
            const row = out[t * self.d_model .. (t + 1) * self.d_model];
            if (tid >= self.vocab_size) {
                @memset(row, 0);
            } else {
                const src = self.table[@as(usize, @intCast(tid)) * self.d_model .. @as(usize, @intCast(tid) + 1) * self.d_model];
                @memcpy(row, src);
            }
        }
    }
};
