// autoreg.zig
const std = @import("std");
const tokenizer = @import("tokenizer.zig");
const embeddings = @import("embeddings.zig");
const posenc = @import("posenc.zig");
const enc = @import("encoder_block.zig");
const dec = @import("decoder_block.zig");
const layernorm = @import("layernorm.zig");
const utils = @import("utils.zig");

pub const Autoregressive = struct {
    allocator: std.mem.Allocator,
    d_model: usize,
    n_layers: usize,
    tok: tokenizer.Tokenizer,
    emb: embeddings.Embeddings,
    blocks: []enc.EncoderBlock,
    ln_f: layernorm.LayerNorm,

    pub fn init(allocator: std.mem.Allocator, vocab_size: usize, d_model: usize, n_layers: usize, n_heads: usize, d_hidden: usize) !Autoregressive {
        var blocks = try allocator.alloc(enc.EncoderBlock, n_layers);
        for (0..n_layers) |i| {
            blocks[i] = try enc.EncoderBlock.init(allocator, d_model, n_heads, d_hidden);
            _ = i;
        }
        return .{
            .allocator = allocator,
            .d_model = d_model,
            .n_layers = n_layers,
            .tok = try tokenizer.Tokenizer.init(allocator),
            .emb = try embeddings.Embeddings.init(allocator, vocab_size, d_model),
            .blocks = blocks,
            .ln_f = try layernorm.LayerNorm.init(allocator, d_model, 1e-5),
        };
    }

    pub fn deinit(self: *Autoregressive) void {
        for (self.blocks) |*b| b.deinit();
        self.allocator.free(self.blocks);
        self.emb.deinit();
        self.ln_f.deinit();
        self.tok.deinit();
    }

    pub fn forward_logits(self: *Autoregressive, text: []const u8) ![]f64 {
        const ids = try self.tok.tokenize(text);
        defer self.allocator.free(ids);

        const seq_len = ids.len;
        var x = try self.allocator.alloc(f64, seq_len * self.d_model);
        defer self.allocator.free(x);

        try self.emb.forward(ids, x);
        try posenc.add_sinusoidal_posenc(x, seq_len, self.d_model);

        for (self.blocks) |*b| {
            try b.forward(x, seq_len);
        }

        try self.ln_f.forward(x, seq_len);

        // Pool last token for logits via linear probe
        var w = try self.allocator.alloc(f64, self.emb.vocab_size * self.d_model);
        defer self.allocator.free(w);
        @memset(w, 0);
        for (0..@min(w.len, self.d_model)) |i| w[i] = 0.01;

        var logits = try self.allocator.alloc(f64, self.emb.vocab_size);
        const last = x[(seq_len - 1) * self.d_model .. seq_len * self.d_model];

        // matvec: logits[v] = dot(w[v,:], last)
        for (0..self.emb.vocab_size) |v| {
            var acc: f64 = 0.0;
            const row = w[v * self.d_model .. (v + 1) * self.d_model];
            for (0..self.d_model) |j| acc += row[j] * last[j];
            logits[v] = acc;
        }
        return logits;
    }

    pub fn generate_next(self: *Autoregressive, text: []const u8) ![]u8 {
        var logits = try self.forward_logits(text);
        defer self.allocator.free(logits);
        utils.softmax_inplace(logits);
        const id = utils.argmax(logits);
        var arr = try std.ArrayList(u32).initCapacity(self.allocator, 1);
        defer arr.deinit();
        try arr.append(@as(u32, @intCast(id)));
        return try self.tok.detokenize(arr.items);
    }
};
